353	     *  late charge). */
354	    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
355	        this.rates = rates;
356	        this.grades = grades;
357	        this.floor = sheet.getFloor();
358	        this.latePct = sheet.getLatePct();
359	        this.today = sheet.getToday();
360	        this.policyDate = sheet.policyDateInForce();
361	    }
362	
363	    /** How the claim's live figures round: half up when the date it rounds by is before the policy date, else half
364	     *  to even. */
365	    public RoundingMode rounding(Claim claim) {
366	        return claim.getRoundsOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
367	    }
368	
369	    /** Whether a claim is overdue: it is OPEN or PENDING and its due-by (fixed when it was created) is before the sheet's today. */
370	    public boolean overdue(Claim claim) {
371	        return claim.getStatus().isOpen() && claim.getDueBy().isBefore(today);
