702	public interface ClaimRepository extends JpaRepository<Claim, Long> {
703	
704	    /** The sheet's claims, newest first. */
705	    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);
706	
707	    /** The sheet's claims in the order they are listed: newest first, a moved claim as its new person's newest. */
708	    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);
709	
710	    /** Lists the claim as the newest: gives it the next listing key. */
711	    @Modifying
712	    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
713	    int relist(@Param("id") Long id);
714	
715	    /** The person's claims, newest first. */
716	    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);
717	
718	    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);
719	
720	    /** The person's claims given this number (at most one: numbers are never reused on a sheet). */
721	    List<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);
722	
723	    /** Refuses a correction unless the claim it corrects is a SETTLED claim of the same person; gives that
724	     *  claim's date (null when it is not a correction). */
725	    default LocalDate checkCorrects(String sheetId, Long personId, String corrects) throws InvalidClaimException {
726	        if (corrects == null) {
727	            return null;
728	        }
729	        return findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects).stream()
730	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).map(Claim::getDate).findFirst()
731	                .orElseThrow(() -> new InvalidClaimException("A correction must name a settled claim of the same person."));
732	    }
733	
734	    /** Takes the sheet's next claim number; the update locks the sheet's row until the transaction ends, so
735	     * two claims opened at once are numbered one after the other. */
736	    @Modifying
737	    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :sheetId",
738	            nativeQuery = true)
739	    int takeNextNumber(@Param("sheetId") String sheetId);
740	
741	    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :sheetId", nativeQuery = true)
742	    int lastNumber(@Param("sheetId") String sheetId);
743	
744	    /** Locks the sheet's row until the transaction ends without taking a number, so two claims opened at once in
745	     *  one per-period sequence are numbered one after the other. */
746	    @Modifying
747	    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :sheetId", nativeQuery = true)
748	    int lockSheet(@Param("sheetId") String sheetId);
749	
750	    /** The last number given out in one of the sheet's per-period sequences; null when it has given none. */
751	    @Query(value = "SELECT last_number FROM claim_sequence WHERE sheet_id = :sheetId AND seq = :seq", nativeQuery = true)
752	    Integer lastInSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
753	
754	    @Modifying
755	    @Query(value = "INSERT INTO claim_sequence (sheet_id, seq, last_number) VALUES (:sheetId, :seq, 1)", nativeQuery = true)
756	    int startSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
757	
758	    @Modifying
759	    @Query(value = "UPDATE claim_sequence SET last_number = last_number + 1 WHERE sheet_id = :sheetId AND seq = :seq",
760	            nativeQuery = true)
761	    int advanceSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
762	
763	    /** Takes the next number in one of the sheet's per-period sequences (from 1); call with the sheet locked. */
764	    default int takeNextInSequence(String sheetId, String seq) {
765	        Integer last = lastInSequence(sheetId, seq);
766	        if (last == null) {
767	            startSequence(sheetId, seq);
768	            return 1;
769	        }
770	        advanceSequence(sheetId, seq);
771	        return last + 1;
772	    }
773	}
