811	package net.officefloor.hq.app.claim;
812	
813	/**
814	 * A claim's status: it starts DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling one above the
815	 * clerk limit leaves it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or
816	 * PENDING claim can be voided (VOID). SETTLED and VOID are final. Only OPEN, PENDING and SETTLED claims count toward
817	 * totals.
818	 */
819	public enum ClaimStatus {
820	    DRAFT, OPEN, PENDING, SETTLED, VOID;
821	
822	    /** The status an action ("open", "settle", "approve", "reject", "void") moves this one to, or null when it is not
823	     *  allowed. A settle above the clerk limit by a clerk ends in PENDING instead. */
824	    public ClaimStatus after(String action) {
825	        return switch (action) {
826	            case "open" -> this == DRAFT ? OPEN : null;
827	            case "settle" -> this == OPEN ? SETTLED : null;
828	            case "approve" -> this == PENDING ? SETTLED : null;
829	            case "reject" -> this == PENDING ? OPEN : null;
830	            case "void" -> this == DRAFT || this == OPEN || this == PENDING ? VOID : null;
831	            default -> null;
832	        };
833	    }
834	
835	    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the
836	     *  totals). */
837	    public boolean isOpen() {
838	        return this == OPEN || this == PENDING;
839	    }
840	
841	    /** The audit event recorded on entering this status. */
842	    public String event() {
843	        return switch (this) {
844	            case OPEN -> "CLAIM_OPENED";
845	            case PENDING -> "CLAIM_PENDING";
846	            case SETTLED -> "CLAIM_SETTLED";
847	            case VOID -> "CLAIM_VOIDED";
848	            case DRAFT -> "CLAIM_DRAFTED";
849	        };
850	    }
851	}
