970	package net.officefloor.hq.app.claim;
971	
972	import java.math.BigDecimal;
973	import java.time.LocalDate;
974	import java.time.format.DateTimeParseException;
975	import java.util.regex.Pattern;
976	import net.officefloor.plugin.variable.Out;
977	import org.springframework.web.bind.annotation.RequestBody;
978	
979	/**
980	 * Reads the claim form from the body; refuses an amount that is missing or has more than two decimals, a date
981	 * that is not a calendar date, and a corrects that is not a claim number. A negative amount (a correction) must
982	 * name the claim it corrects, and only a negative amount may. A blank date is left for the sheet's today.
983	 */
984	public class ValidateClaim {
985	
986	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
987	
988	    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");
989	
990	    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
991	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
992	        String date = request == null || request.date() == null ? "" : request.date().trim();
993	        String note = request == null || request.note() == null ? "" : request.note().trim();
994	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
995	        if (!AMOUNT.matcher(amount).matches()) {
996	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
997	        }
998	        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
999	            throw new InvalidClaimException("Corrects must be a claim number.");
1000	        }
1001	        BigDecimal value = new BigDecimal(amount).setScale(2);
1002	        if (value.signum() < 0 && corrects.isEmpty()) {
1003	            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
1004	        }
1005	        if (value.signum() >= 0 && !corrects.isEmpty()) {
1006	            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
1007	        }
1008	        LocalDate parsed = null;
1009	        if (!date.isEmpty()) {
1010	            try {
1011	                parsed = LocalDate.parse(date);
1012	            } catch (DateTimeParseException e) {
1013	                throw new InvalidClaimException("Not a date: " + date);
1014	            }
1015	        }
1016	        body.set(new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects));
1017	    }
1018	}
